function findPrefixScore(nums) {
  const ans = new Array(nums.length);
  let maxSoFar = 0;
  let score = 0;
  for (let i = 0; i < nums.length; i++) {
    maxSoFar = Math.max(maxSoFar, nums[i]);
    score += nums[i] + maxSoFar;
    ans[i] = score;
  }
  return ans;
}

