function findPrefixScore(nums) {
  const result = [];
  for (let end = 0; end < nums.length; end++) {
    // Rebuild the companion array of nums[0..end] from scratch and add it up.
    let total = 0;
    for (let j = 0; j <= end; j++) {
      let top = nums[0];
      for (let t = 1; t <= j; t++) if (nums[t] > top) top = nums[t];
      total += nums[j] + top;
    }
    result.push(total);
  }
  return result;
}

