function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const top = rand() < 0.6 ? int(1, 10) : 1000000000;
    const nums = Array.from({ length: n }, () => int(1, top));
    const shape = rand();
    if (shape < 0.2) nums.sort((a, b) => a - b);
    else if (shape < 0.4) nums.sort((a, b) => b - a);
    return [nums];
  }
  const n = int(1500, 2000);
  const mode = rand();
  const nums = Array.from({ length: n }, () => int(1, 1000000000));
  if (mode < 0.25) nums.sort((a, b) => a - b);
  else if (mode < 0.5) nums.sort((a, b) => b - a);
  else if (mode < 0.65) nums.fill(1000000000);
  return [nums];
}
